#### 面试题 05.01. 插入
(https://leetcode.cn/problems/insert-into-bits-lcci/)
```cpp
// 分成三段然后组合 38.29
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		int front = 0, tail = 0;
		if(j == 31 && i == 0) {
			return M;
        }
        else if (j == 31 && i != 0) {
			// tail = (N << (32 - i)) >> (32 - i);
			tail = N & ((1 << i) - 1);
			return (M << i) + tail;
		} else if(j != 31 && i == 0) {
			front = (N >> (j + 1)) << (j + 1);
			return front + M;
		} else {
			front = (N >> (j + 1)) << (j + 1);
			// tail = (N << (32 - i)) >> (32 - i);
			tail  = N & ((1 << i) - 1);
			return front + tail + (M << i);
		}
		return 0;
	}
};
```
- 如果使用注释部分内容那么使用之前要保留一个 N 的备份，否则前面的修改正确，后面再用**失真的数据**结果出错
还可以使用位掩码：
```cpp
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		// 1. 创建掩码：将 i~j 位清零
		int mask = 0;
		for(int k = i; k <= j; k++) {
			mask |= (1 << k);
		}
		mask = ~mask;  // 取反，用于清零 i~j 位

		// 2. 清零 N 的 i~j 位
		N &= mask;

		// 3. 将 M 左移 i 位后与 N 合并
		M <<= i;
		return N | M;
	}
};
```
使用更优雅的解法，用法参考[[用法导向知识#位运算#其他操作技巧]]
```cpp
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		// 清除 N 中 i~j 位的值
		for(int k = i; k <= j; k++) {
			if(N & (1 << k)) {	// 如果第 k 位是 1
				N -= (1 << k);	// 清除该位
			}
		}

		// 插入 M
		return N | (M << i);
	}
};
```

